CREATE TABLE "${primehrSchema}".rr_evaluation_case(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,nomination_id VARCHAR(36) NOT NULL,cycle_id VARCHAR(36) NOT NULL,category_version_id VARCHAR(36) NOT NULL,charter_version_id VARCHAR(36) NOT NULL,charter_definition_version INTEGER NOT NULL,charter_fingerprint VARCHAR(64) NOT NULL,status VARCHAR(40) NOT NULL,eligibility_summary VARCHAR(4000),eligibility_decided_by VARCHAR(100),eligibility_decided_at TIMESTAMP WITH TIME ZONE,calculated_score NUMERIC(10,4),eligible_voters INTEGER,attending_voters INTEGER,quorum_met BOOLEAN,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_rr_eval_nomination FOREIGN KEY(nomination_id) REFERENCES "${primehrSchema}".rr_nomination(id),CONSTRAINT fk_rr_eval_cycle FOREIGN KEY(cycle_id) REFERENCES "${primehrSchema}".rr_award_cycle(id),CONSTRAINT fk_rr_eval_category FOREIGN KEY(category_version_id) REFERENCES "${primehrSchema}".rr_award_category_version(id),CONSTRAINT fk_rr_eval_charter FOREIGN KEY(charter_version_id) REFERENCES "${primehrSchema}".rr_committee_charter_version(id),CONSTRAINT uk_rr_evaluation_nomination UNIQUE(agency_id,nomination_id),CONSTRAINT ck_rr_eval_status CHECK(status IN('ELIGIBILITY_REVIEW','ELIGIBLE','DISQUALIFIED','RETURNED','EVALUATION','DELIBERATION','RECOMMENDED','NOT_RECOMMENDED','FINAL_APPROVED','FINAL_DISAPPROVED','RECONSIDERATION_PENDING')));
CREATE INDEX ix_rr_eval_status ON "${primehrSchema}".rr_evaluation_case(agency_id,status,cycle_id);
CREATE TABLE "${primehrSchema}".rr_eligibility_finding(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,evaluation_case_id VARCHAR(36) NOT NULL,rule_code VARCHAR(100) NOT NULL,normalized_rule_code VARCHAR(100) NOT NULL,rule_label VARCHAR(300) NOT NULL,outcome VARCHAR(30) NOT NULL,rationale VARCHAR(3000) NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_rr_finding_case FOREIGN KEY(evaluation_case_id) REFERENCES "${primehrSchema}".rr_evaluation_case(id),CONSTRAINT uk_rr_eligibility_rule UNIQUE(agency_id,evaluation_case_id,normalized_rule_code),CONSTRAINT ck_rr_finding_outcome CHECK(outcome IN('PASS','FAIL','NOT_APPLICABLE')));
CREATE TABLE "${primehrSchema}".rr_evaluator_assignment(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,evaluation_case_id VARCHAR(36) NOT NULL,employee_no VARCHAR(100) NOT NULL,display_name VARCHAR(250) NOT NULL,position_title VARCHAR(250) NOT NULL,member_role VARCHAR(30) NOT NULL,voting_member BOOLEAN NOT NULL,status VARCHAR(20) NOT NULL,conflict_declared BOOLEAN NOT NULL,conflict_reason VARCHAR(2000),replacement_assignment_id VARCHAR(36),attending BOOLEAN NOT NULL,total_score NUMERIC(10,4),submitted_at TIMESTAMP WITH TIME ZONE,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_rr_assignment_case FOREIGN KEY(evaluation_case_id) REFERENCES "${primehrSchema}".rr_evaluation_case(id),CONSTRAINT fk_rr_assignment_replacement FOREIGN KEY(replacement_assignment_id) REFERENCES "${primehrSchema}".rr_evaluator_assignment(id),CONSTRAINT uk_rr_evaluator_employee UNIQUE(agency_id,evaluation_case_id,employee_no),CONSTRAINT ck_rr_assignment_status CHECK(status IN('ASSIGNED','RECUSED','REPLACED','SUBMITTED')));
CREATE INDEX ix_rr_assignment_case ON "${primehrSchema}".rr_evaluator_assignment(agency_id,evaluation_case_id,status);
CREATE TABLE "${primehrSchema}".rr_criterion_rating(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,assignment_id VARCHAR(36) NOT NULL,criterion_id VARCHAR(36) NOT NULL,criterion_code VARCHAR(80) NOT NULL,weight_percent NUMERIC(7,2) NOT NULL,maximum_score NUMERIC(10,2) NOT NULL,raw_score NUMERIC(10,2) NOT NULL,weighted_score NUMERIC(10,4) NOT NULL,comments VARCHAR(3000) NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_rr_rating_assignment FOREIGN KEY(assignment_id) REFERENCES "${primehrSchema}".rr_evaluator_assignment(id),CONSTRAINT fk_rr_rating_criterion FOREIGN KEY(criterion_id) REFERENCES "${primehrSchema}".rr_award_criterion(id),CONSTRAINT uk_rr_rating_criterion UNIQUE(agency_id,assignment_id,criterion_id),CONSTRAINT ck_rr_rating_range CHECK(raw_score>=0 AND raw_score<=maximum_score));
CREATE TABLE "${primehrSchema}".rr_decision_event(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,evaluation_case_id VARCHAR(36) NOT NULL,event_type VARCHAR(40) NOT NULL,outcome VARCHAR(30) NOT NULL,calculated_score NUMERIC(10,4),eligible_voters INTEGER,attending_voters INTEGER,quorum_met BOOLEAN,reason VARCHAR(4000) NOT NULL,decided_by VARCHAR(100) NOT NULL,decided_at TIMESTAMP WITH TIME ZONE NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_rr_decision_case FOREIGN KEY(evaluation_case_id) REFERENCES "${primehrSchema}".rr_evaluation_case(id),CONSTRAINT ck_rr_decision_type CHECK(event_type IN('COMMITTEE_RECOMMENDATION','FINAL_DECISION','RECONSIDERATION_RESOLUTION')),CONSTRAINT ck_rr_decision_outcome CHECK(outcome IN('RECOMMEND','NOT_RECOMMEND','RETURN','DISQUALIFY','APPROVE','DISAPPROVE')));
CREATE INDEX ix_rr_decision_case ON "${primehrSchema}".rr_decision_event(agency_id,evaluation_case_id,decided_at);
CREATE TABLE "${primehrSchema}".rr_decision_issue(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,evaluation_case_id VARCHAR(36) NOT NULL,grounds VARCHAR(4000) NOT NULL,status VARCHAR(20) NOT NULL,filed_by VARCHAR(100) NOT NULL,filed_at TIMESTAMP WITH TIME ZONE NOT NULL,resolution_reason VARCHAR(4000),resolved_by VARCHAR(100),resolved_at TIMESTAMP WITH TIME ZONE,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_rr_issue_case FOREIGN KEY(evaluation_case_id) REFERENCES "${primehrSchema}".rr_evaluation_case(id),CONSTRAINT ck_rr_issue_status CHECK(status IN('OPEN','RESOLVED','DISMISSED')));
